# application.yml
p016:
  log-titulo: "(S151)S151/FILE/MOVS{sistema}/{fechaAammdd} ON {pack}."   # WKS-TIT-LOG151
  pack-default: LOGS                  # si L001/CONTROL no devuelve WKS-B01-NOMPACMOV
  hora-inicio: "04:00:00"             # WKS-HORA-INICIO
  hora-limite: "20:00:00"             # WKS-HORA-LIMITE
  flush-cada-transacciones: 100       # W77-TRANSACCIONES > 99
  espera-sin-datos: 5s                # W77-TIME = 5 (WAIT UNTIL)

