/** WKS-PARAMETRO 9(12): FECHA 9(08) + SISTEMA 9(04). Se pasa como JobParameters. */
public record ParametroP016(LocalDate fecha, int sistema) {
    static ParametroP016 de(JobParameters p) {
        return new ParametroP016(p.getLocalDate("fecha"), p.getLong("sistema").intValue());
    }
}

/** HI-INTERRUPT: el operador manda TASKVALUE con HI; se mapean a señales de control. */
public enum SenalOperador {
    MOSTRAR_LEIDOS(20),   // W88-HI20 -> 070000-DISPLAY-REGLEIDOS
    TERMINAR(4);          // W88-HI4  -> W77-END-LOGS = 1
    // Cualquier valor mayor que 20 cambia el intervalo de espera (W77-TIME).
    final int codigo;
    SenalOperador(int codigo) { this.codigo = codigo; }
}

/** WKS-TOT-PIMC 9(12) redefinido como producto 9(04), instrumento 9(02), moneda 9(02), CPAE 9(04). */
public record LlaveTotales(int producto, int instrumento, int moneda, int cpae) {
    /** WKS-ALE-PIM 9(08): las alarmas se configuran sin CPAE. */
    LlaveAlarma sinCpae() { return new LlaveAlarma(producto, instrumento, moneda); }
}
public record LlaveAlarma(int producto, int instrumento, int moneda) {}

/** Una entrada de WKS-TOT-ABO y WKS-TOT-CGO con el mismo subíndice. */
public final class Totales {
    long numCargos, numAbonos;                                         // 9(06) COMP
    BigDecimal impCargos = BigDecimal.ZERO.setScale(2);                 // 9(14)V99 COMP
    BigDecimal impAbonos = BigDecimal.ZERO.setScale(2);
}

/** Límites por importe de una sola transacción (no acumulados), en pesos enteros: 9(12) COMP. */
public record LimitesAlarma(BigDecimal limiteAbono, BigDecimal limiteCargo) {}

@Component
@StepScope
public class TablaIntradia {
    static final int CAPACIDAD_ORIGINAL = 3000;
    private final Map<LlaveTotales, Totales> totales = new LinkedHashMap<>();   // conserva el orden de alta
    private final Map<LlaveAlarma, LimitesAlarma> limites = new HashMap<>();

    Totales obtenOCrea(LlaveTotales k) {
        if (!totales.containsKey(k) && totales.size() == CAPACIDAD_ORIGINAL) {
            log.warn("Se excede la capacidad de 3000 de la tabla COBOL: {}", k);   // en COBOL no hay control
        }
        return totales.computeIfAbsent(k, x -> new Totales());
    }
}

@Component
@RequiredArgsConstructor
public class VentanaOperativa {

    private final AcumuladorProperties props;
    private final Clock clock;

    /** Si ya pasó la hora límite, el proceso termina con mensaje y no hace nada. */
    void validaHoraLimite() {
        LocalTime ahora = LocalTime.now(clock);
        if (ahora.isAfter(props.horaLimite())) {
            throw new FueraDeVentanaException("ESTE PROCESO NO PUEDE CORRER DESPUES DE LAS "
                    + props.horaLimite().format(DateTimeFormatter.ofPattern("HHmm")) + " HRS.");
        }
    }

    /** 000020-VALIDA-INICIO: WAIT(20) hasta pasar la hora de inicio; se reemplaza por una espera programada. */
    void esperaHoraInicio(BooleanSupplier terminar) throws InterruptedException {
        while (!LocalTime.now(clock).isAfter(props.horaInicio()) && !terminar.getAsBoolean()) {
            Thread.sleep(Duration.ofSeconds(20));
        }
    }
}

// L001/CONTROL (CONSISDIA función 01) con hasta seis intentos separados por 3 segundos.
@Retryable(maxAttempts = 6, backoff = @Backoff(delay = 3000))
String packDelLog(int sistema, int csi) { return control.consisDia(1, sistema, csi).packOr("LOGS"); }

/**
 * ItemReader que sigue un archivo que otro proceso sigue escribiendo (L002 REGISTRAS).
 * L01-DATOS (bloque de 145) recorre lo acumulado; L02-DATOS (bloque de 2) lee la cola
 * reciente sin datos viejos en buffer. Aquí basta un acceso por posición con relectura.
 */
@Component
@StepScope
@RequiredArgsConstructor
public class LogTailItemReader implements ItemStreamReader<MovimientoLog151> {

    private final LogDiarioRepository log;     // LOG del día; en el to-be, tabla o tópico Kafka
    private final VentanaOperativa ventana;
    private final AcumuladorProperties props;
    private long llave;                        // W77-LLAVE: número de registro relativo

    @Override
    public MovimientoLog151 read() throws InterruptedException {
        while (true) {
            if (ventana.pasoHoraLimite() || senales.terminar()) return null;   // W77-SW-FIN = 9 / HI4
            Optional<MovimientoLog151> m = log.leePorPosicion(llave + 1);
            if (m.isPresent() && m.get().funcion() != 99) { llave++; return m.get(); }
            Thread.sleep(props.esperaSinDatos());          // WAIT UNTIL W77-TIME
            // Cada 24 esperas el fuente cierra y reabre los dos archivos para ver el crecimiento.
        }
    }

    @Override public void update(ExecutionContext ctx) { ctx.putLong("llave", llave); }   // reinicio
    @Override public void open(ExecutionContext ctx)   { llave = ctx.getLong("llave", nivelEnBifin()); }
}

@Component
@StepScope
@RequiredArgsConstructor
public class FiltroMovimientos implements ItemProcessor<MovimientoLog151, MovimientoLog151> {

    private final AcumuladorProperties props;   // exclusiones: [{sistema: 500, tipos-proceso: [40, 41, 42, 43]}]

    @Override
    public MovimientoLog151 process(MovimientoLog151 m) {
        if (props.excluido(m.sistema(), m.tipoProceso())) return null;   // filtro Teletón (sistema 500)
        return switch (m.funcion()) {
            case 1 -> m.origen() == 1 || m.origen() == 2 ? m : null;     // alta: solo orígenes 1 y 2
            case 2 -> m;                                                  // eliminación: se revierte
            default -> null;                                              // cualquier otra función
        };
    }
}

@Bean
Step acumulaIntradia(JobRepository repo, PlatformTransactionManager tx, LogTailItemReader lector,
                     FiltroMovimientos filtro, AcumuladorWriter writer) {
    return new StepBuilder("acumulaIntradia", repo)
            .<MovimientoLog151, MovimientoLog151>chunk(100, tx)   // W77-TRANSACCIONES > 99 -> 001900-ACT-BASE
            .reader(lector).processor(filtro).writer(writer)
            .build();
}

/** 001500-GUARDA-TABLA: llave del movimiento; el CPAE solo aplica al sistema 18. */
void acumula(MovimientoLog151 m) {
    int cpae = (sistema == props.sistemaConCpae())                      // WKS-SISTE-PARAM = 18
            ? cpaes.porSucursalOperadora(m.sucursalOperadora()).orElse(0) // 045500-TRAE-CEPAE
            : 0;
    var llave = new LlaveTotales(m.producto(), m.instrumento(), m.moneda(), cpae);
    Totales t = tabla.obtenOCrea(llave);                                  // 001600 + 001800 en un paso
    for (SlotContable s : m.slotsHastaClaveCero()) {                      // UNTIL CVETRAN(W77-IND) = 0
        Naturaleza nat = naturaleza.de(s, formatoCatalogo);               // 001715-ACUMULA
        switch (nat) {
            case CARGO -> { t.numCargos++; t.impCargos = t.impCargos.add(s.importe()); }
            case ABONO -> { t.numAbonos++; t.impAbonos = t.impAbonos.add(s.importe()); }
            case NINGUNA -> { }
        }
        alarmas.evalua(m, s, nat, llave.sinCpae());
    }
}

/** Naturaleza contable del slot, idéntica en 001715-ACUMULA y 001800-MVE-TABLA. */
public enum Naturaleza { CARGO, ABONO, NINGUNA;

    static Naturaleza de(SlotContable s, int formatoCatalogo, CatalogoClaves cat) {
        int clave = s.claveTransaccion();
        int nat = (formatoCatalogo == 3 && (s.esquemaContable() == 1 || s.esquemaContable() == 2)
                   && cat.tipoMovimiento(clave) != 1)
                ? cat.naturaleza2(clave)        // WKS-CAT-NATCON2
                : cat.naturaleza(clave);        // WKS-CAT-NATCON
        return switch (nat) { case 1 -> CARGO; case 2 -> ABONO; default -> NINGUNA; };
    }
}

// Comportamiento COBOL que NO se replica (ver riesgo): al dar de alta la combinación,
// cada slot pone en cero el lado contrario, así que un cargo seguido de un abono
// en el mismo movimiento deja solo el abono.
// if (props.compatibilidadAltaCobol()) { t.numCargos = 0; t.impCargos = ZERO; }

/** 001880-APLICA-ELIMINACION: sigue la cadena de autorizaciones anteriores y resta cada original. */
void revierte(MovimientoLog151 eliminacion) {
    long autorizacion = eliminacion.autAEliminarS151();
    while (autorizacion != 0) {
        Optional<MovimientoLog151> orig = log.leePorPosicion(autorizacion + 1);
        if (orig.isEmpty() || orig.get().funcion() != 1) break;
        var o = orig.get();
        var llave = new LlaveTotales(o.producto(), o.instrumento(), o.moneda(), cpaeDe(o));
        Totales t = tabla.busca(llave).orElse(null);
        if (t != null) {
            for (SlotContable s : o.slotsHastaClaveCero()) {
                // Se usa la MISMA naturaleza que en la suma; el fuente usa solo NATCON (ver riesgo).
                switch (Naturaleza.de(s, formatoCatalogo, catalogo)) {
                    case CARGO -> { t.numCargos--; t.impCargos = restaNoNegativa(t.impCargos, s.importe()); }
                    case ABONO -> { t.numAbonos--; t.impAbonos = restaNoNegativa(t.impAbonos, s.importe()); }
                    case NINGUNA -> { }
                }
            }
        }
        autorizacion = o.autAnteriorS151();      // A00-R01-AUT-ANT-S151
    }
}

/** 9(14)V99 COMP no tiene signo: un resultado negativo se guardaría como valor absoluto. */
private static BigDecimal restaNoNegativa(BigDecimal a, BigDecimal b) {
    BigDecimal r = a.subtract(b);
    if (r.signum() < 0) throw new TotalNegativoException(a, b);
    return r;
}

@Service
@RequiredArgsConstructor
public class AlarmaService {

    private final Map<LlaveAlarma, LimitesAlarma> limites;       // WKS-TABLA-ALERTAS
    private final AlarmaRepository alarmas;                       // S151B03ALARMAS

    /** 050000/050100: compara el importe del slot, no el acumulado, contra el límite. */
    void evalua(MovimientoLog151 m, SlotContable s, Naturaleza nat, LlaveAlarma llave) {
        LimitesAlarma lim = limites.get(llave);
        if (lim == null || nat == Naturaleza.NINGUNA) return;
        boolean excede = switch (nat) {
            case ABONO -> s.importe().compareTo(lim.limiteAbono()) > 0;
            case CARGO -> s.importe().compareTo(lim.limiteCargo()) > 0;
            default -> false;
        };
        if (excede) {
            alarmas.save(Alarma.de(m, s, nat == Naturaleza.ABONO ? 2 : 1));   // CVE-ALARM 2 abono, 1 cargo
        }
    }
}

@Component
@RequiredArgsConstructor
public class AcumuladorWriter implements ItemWriter<MovimientoLog151> {

    private final TotalesProductoRepository repo;    // S151B01TOTPROD en S151BD13BIFIN

    @Override
    @Transactional
    public void write(Chunk<? extends MovimientoLog151> chunk) {
        chunk.forEach(acumulador::aplica);           // suma o revierte en memoria
        for (var e : tabla.conMovimiento()) {        // 002010: solo entradas con algún total > 0
            var id = new TotalesProductoId(sistema, csi, fecha, e.getKey());
            TotalesProducto fila = repo.findByIdForUpdate(id)        // LOCK B01SXTOTPROD
                    .orElseGet(() -> TotalesProducto.nuevo(id));     // NOTFOUND -> CREATE
            fila.sobrescribe(e.getValue());                         // 030100: MOVE, no ADD
            repo.save(fila);                                        // STORE S151B01TOTPROD
        }
        control.actualizaNivel(sistema, lector.llave());            // 031100-ACT-GLOB-C10MIN
    }
}
